 const c=current(),a=selectedAlternative(c),p=terrProfile(a.location,c.referenceYear||2024),qs=TERRITORIAL.questions(p,c.sector),node=byId('policy-territorial-decision');if(!node)return;
 const list=qs.map(q=>{const e=c.evidence[q.evidenceId]||{};const ok=evOk(e);return `<div class="terr-evidence-row"><span class="terr-q-gate">${q.gate}</span><div><b>${safe(q.headline)}</b><p>${safe(q.observation)}</p><p><strong>Pertanyaan:</strong> ${safe(q.prompt)}</p><small><strong>Bukti penentu:</strong> ${safe(q.requirement)}</small><small>Checklist terkait: ${safe(EVIDENCE.find(x=>x.id===q.evidenceId)?.title||q.evidenceId)} · ${ok?'sumber dicatat oleh pengguna, bukan diverifikasi':'belum didukung rujukan lengkap'}</small></div></div>`;}).join('');
 node.innerHTML=`<div class="terr-recommendations"><div class="terr-heading"><div><span class="policy-stage-count">REKOMENDASI BERDASARKAN PANEL / KETERLACAKAN</span><h3>${qs.length} pertanyaan material untuk ${safe(p.name)}</h3><p>Opsi fokus: ${safe(a.name)} · skor ${terrFmt(p.score,2)}, tahun ${p.year}. Perubahan wilayah dapat mengubah pertanyaan, bukan menghasilkan jawaban tentang tapak.</p></div><span class="terr-pill">G0–G4</span></div><div class="terr-evidence-list">${list}</div><p class="terr-caution">Tidak ada label “aman”, “layak”, “berisiko tinggi”, atau besar kompensasi dari peringkat maupun proksi teritorial. Batas hukum dan dampak residual memerlukan penilaian resmi.</p></div>`;
