function territorialDossier(c,ge){
 const yr=c.referenceYear||2024;
 const cols=['Rancangan','BPS','Tahun','J-NEST','Peringkat','IDI','SEC','ESP','NDVI','NDBI','LST °C','Kemiskinan %','TPT %'];
 const rows=c.alternatives.map(a=>{const p=terrProfile(a.location,yr),key=id=>p.indicators.find(x=>x.id===id).value;const vals=[a.name+' — '+p.name,p.code,yr,terrFmt(p.score,3),p.rank,terrFmt(p.IDI,3),terrFmt(p.SEC,3),terrFmt(p.ESP,3),terrFmt(key('ndvi'),3),terrFmt(key('ndbi'),3),terrFmt(key('lst'),2),terrFmt(key('poor'),2),terrFmt(key('tpt'),2)];return `<tr>${vals.map(v=>`<td>${ge(v)}</td>`).join('')}</tr>`;}).join('');
 const p=terrProfile(selectedAlternative(c).location,yr),qs=TERRITORIAL.questions(p,c.sector);
 const fact=`<h3>Jejak data wilayah–tahun dan sensitivitas (bukan prakiraan proyek)</h3><table><thead><tr>${cols.map(x=>`<th>${ge(x)}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table><p class="note">Metode: gabungan 135 observasi untuk normalisasi min–maks; bobot CRITIC per dimensi, antardimensi 1/3. Tipologi hanya untuk 2024. Bobot/sumber dapat diaudit dari tiga CSV dan skrip reproduksi. Nilai daerah <b>tidak</b> memverifikasi situasi tapak atau mengukur pengaruh memindahkan proyek.</p>`;
 const qtable=`<h3>Pertanyaan teritorial yang harus dijawab dengan bukti tapak (opsi fokus: ${ge(p.name)})</h3><table><thead><tr><th>Gate</th><th>Temuan proksi dan pertanyaan</th><th>Data/dokumen yang diperlukan</th><th>Status input penelaah</th></tr></thead><tbody>${qs.map(q=>{const e=c.evidence[q.evidenceId]||{};return `<tr><td>${ge(q.gate)}</td><td><b>${ge(q.headline)}</b><small>${ge(q.observation)}</small>${ge(q.prompt)}</td><td>${ge(q.requirement)}</td><td>${ge(EVSTAT[e.status]||'Belum diperiksa')}<small>${ge(e.source||'Tanpa sumber')}</small></td></tr>`;}).join('')}</tbody></table>`;
 return `<h3>2a · Bukti teritorial yang terhubung ke setiap alternatif</h3>${fact}${qtable}<p class="note">Panel olahan penelitian 2020–2024 · Kode BPS, indikator dan metode tersedia di tiga CSV dalam paket aplikasi. Pemeriksaan ini belum menggantikan audit sumber BPS/GEE atau pengukuran tapak.</p>`;
}
function exportTerritorial(){
 const c=current(),yr=c.referenceYear||2024,rows=[['kategori','alternatif','kab_kota','bps_domain','tahun_panel','id','gate','label_atau_pertanyaan','nilai_teritorial','satuan','median_27','keterangan_atau_bukti','sumber']];
 for(const a of c.alternatives){const p=terrProfile(a.location,yr);for(const f of p.indicators)rows.push(['indikator_utama',a.name,p.name,p.code,yr,f.id,'',f.label,f.value,f.unit,f.median,`Bobot CRITIC ${f.criticWeight}; kontribusi skor ${f.compositeContribution}`,'Panel master olahan']);
  for(const f of p.companions)rows.push(['pendamping_bukan_indeks',a.name,p.name,p.code,yr,f.id,'',f.label,f.value??'',f.unit,f.median??'',f.note,'Panel master olahan']);
  for(const q of TERRITORIAL.questions(p,c.sector))rows.push(['pertanyaan_G0_G4',a.name,p.name,p.code,yr,q.evidenceId,q.gate,q.prompt,'','','',q.requirement,q.basis]);
 }
 saveFile('\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n'),'jnest-jejak-teritorial-'+cleanName(c.name)+'.csv','text/csv;charset=utf-8');
 toast('CSV jejak teritorial 8 indikator, proksi pendamping dan pertanyaan G0–G4 telah disiapkan.');
}

